main:
    scores = {"Ada": 92, "Alan": 78, "Grace": 85, "Linus": 90}
    grades = {}
    each name, score in scores.items():
        if score >= 90:
            grades[name] = "A"
        else if score >= 80:
            grades[name] = "B"
        else:
            grades[name] = "C"
        end
    end
    print(grades)
end

use vyrn.csv

create score(rows: list, guesses: list) -> int:
    names = {row["state"].lower() each row in rows}
    guessed = {g.strip().lower() each g in guesses}
    return len(names & guessed)
end

main:
    rows = csv.parse("state,capital\nOhio,Columbus\nTexas,Austin\nMaine,Augusta\n")
    print(score(rows, [" ohio", "Texas", "texas", "Utah"]))
end

create add_bonus(scores: map) -> map:
    return {name: s + 5 each name, s in scores.items()}
end

main:
    let scores = {"ada": 10, "alan": 20}
    let boosted = add_bonus(scores)
    print(scores, boosted)
end

create split_flags(args: list[str]) -> (map, list[str]):
    var flags = {}
    var words = []
    each a in args:
        if a.startswith("--"):
            let parts = a[2:].split("=", 1)
            flags[parts[0]] = parts[1] if len(parts) == 2 else true
        else:
            words.append(a)
        end
    end
    return (flags, words)
end

main:
    print(split_flags(["tidy", "--dry-run", "Downloads", "--limit=5"]))
end
